        "Ambito" character varying(50) NOT NULL,
        "Objeto" text NOT NULL,
        "FechaInicio" timestamp with time zone NOT NULL,
        "FechaVencimiento" timestamp with time zone NOT NULL,
        "Estado" character varying(30) NOT NULL,
        "Supervisor" character varying(200),
        "RenovacionAutomatica" boolean NOT NULL,
        "Observaciones" character varying(500),
        "FechaCreacion" timestamp with time zone NOT NULL,
        "FechaModificacion" timestamp with time zone,
        "UsuarioCreadorId" text,
        CONSTRAINT "PK_Convenios" PRIMARY KEY ("Id"),
        CONSTRAINT "FK_Convenios_Entidades_EntidadId" FOREIGN KEY ("EntidadId") REFERENCES "Entidades" ("Id") ON DELETE CASCADE,
        CONSTRAINT "FK_Convenios_TiposConvenio_TipoConvenioId" FOREIGN KEY ("TipoConvenioId") REFERENCES "TiposConvenio" ("Id") ON DELETE CASCADE,
        CONSTRAINT "FK_Convenios_Usuarios_UsuarioCreadorId" FOREIGN KEY ("UsuarioCreadorId") REFERENCES "Usuarios" ("Id")
    );
