    CREATE INDEX "IX_AreasPromotoras_AreaPadreId" ON "AreasPromotoras" ("AreaPadreId");
    END IF;
END $EF$;

DO $EF$
BEGIN
    IF NOT EXISTS(SELECT 1 FROM "__EFMigrationsHistory" WHERE "MigrationId" = '20260710173524_CatalogosUleamRecursivos') THEN
    ALTER TABLE "AreasPromotoras" ADD CONSTRAINT "FK_AreasPromotoras_AreasPromotoras_AreaPadreId" FOREIGN KEY ("AreaPadreId") REFERENCES "AreasPromotoras" ("Id") ON DELETE RESTRICT;
    END IF;
END $EF$;

DO $EF$
BEGIN
    IF NOT EXISTS(SELECT 1 FROM "__EFMigrationsHistory" WHERE "MigrationId" = '20260710173524_CatalogosUleamRecursivos') THEN
    PERFORM setval(
        pg_get_serial_sequence('"AreasPromotoras"', 'Id'),
        GREATEST(
            (SELECT MAX("Id") FROM "AreasPromotoras") + 1,
            nextval(pg_get_serial_sequence('"AreasPromotoras"', 'Id'))),
        false);
    PERFORM setval(
        pg_get_serial_sequence('"Facultades"', 'Id'),
        GREATEST(
            (SELECT MAX("Id") FROM "Facultades") + 1,
            nextval(pg_get_serial_sequence('"Facultades"', 'Id'))),
        false);
    PERFORM setval(
        pg_get_serial_sequence('"Carreras"', 'Id'),
        GREATEST(
            (SELECT MAX("Id") FROM "Carreras") + 1,
            nextval(pg_get_serial_sequence('"Carreras"', 'Id'))),
        false);
    END IF;
END $EF$;

