DO $EF$
BEGIN
    IF NOT EXISTS(SELECT 1 FROM "__EFMigrationsHistory" WHERE "MigrationId" = '20260930040410_NormalizarAmbitosEIntegridadDatos') THEN
    INSERT INTO "AmbitosConvenio" ("ConvenioId", "Nombre")
    SELECT c."Id", BTRIM(valor)
    FROM "Convenios" AS c
    CROSS JOIN LATERAL regexp_split_to_table(c."Ambito", ',') AS valor
    WHERE BTRIM(valor) <> ''
    ON CONFLICT ("ConvenioId", "Nombre") DO NOTHING;
    END IF;
END $EF$;

